pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(this));
        address initialOwner = c.owner();
        vm.prank(caller);
        c.setOwner(caller);
        if (caller == address(this)) {
            assertEq(c.owner(), caller);
        } else {
            assertEq(c.owner(), initialOwner);
        }
    }
}

