pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(c)); // ensure caller is not the contract itself, which would bypass the admin check via msg.sender
        address originalOwner = c.owner();
        vm.prank(caller);
        c.setOwner(newOwner);
        // After a non-admin call, the owner should remain unchanged in the reference,
        // but in the mutant it changes to newOwner.
        assertEq(c.owner(), originalOwner, "Owner should not change when called by non-admin");
    }
}

