pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(this));
        address originalOwner = c.owner();
        vm.prank(caller);
        c.setOwner(newOwner);
        address currentOwner = c.owner();
        if (caller == address(uint160(uint256(keccak256(abi.encodePacked(address(c))))))) {
            assertTrue(currentOwner == newOwner);
        } else {
            assertTrue(currentOwner == originalOwner);
        }
    }
}

