pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address oldOwner, address newOwner) public {
        vm.assume(caller != address(c)); // admin is the deployer, so we assume a different caller to avoid trivial equality
        vm.assume(oldOwner != newOwner);
        vm.prank(address(this)); // set initial owner to oldOwner using admin
        c.setOwner(oldOwner);
        vm.prank(caller);
        c.setOwner(newOwner);
        assertTrue(c.owner() == oldOwner);
    }
}

