pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address targetOwner) public {
        // Admin is the deployer of C (msg.sender in setUp), which is this test contract.
        // The admin calls setOwner with arbitrary targetOwner.
        (bool ok, bytes memory ret) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, targetOwner));
        // The call must not revert (since it's from the admin), and the returned value must be true.
        assertTrue(ok && abi.decode(ret, (bool)));
    }
}

