pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonAdmin, address newOwner) public {
        vm.assume(nonAdmin != address(this));
        vm.prank(nonAdmin);
        try c.setOwner(newOwner) {
            assertTrue(msg.sender == address(this) || nonAdmin == address(this));
        } catch {
            assertTrue(true);
        }
    }
}
